      --muted: #94a3b8;
      --accent: #60a5fa;
      --accent-strong: #3b82f6;
      --error: #fda4af;
      --error-strong: #fb7185;
      --input: rgba(15, 23, 42, 0.75);
      --shadow: 0 24px 70px rgba(2, 6, 23, 0.45);
