    }

    input[aria-invalid="true"] {
      border-color: var(--error-strong);
      box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.12);
    }

    .helper-text,
    .error-message,
    .success-message {
      font-size: 0.9rem;
      line-height: 1.5;
    }

    .helper-text {
      color: var(--muted);
    }

    .error-message {
      min-height: 1.35em;
      color: var(--error);
    }

    .success-message {
      margin: 6px 0 0;
      color: #86efac;
      min-height: 1.5em;
    }

    .submit-button {
      margin-top: 6px;
      border: 0;
      border-radius: 14px;
      padding: 14px 18px;
      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
      color: #eff6ff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
      box-shadow: 0 16px 32px rgba(37, 99, 235, 0.32);
