     };

     const state = {
       values: {
         fullName: "",
         email: "",
         phone: ""
       },
       errors: {
         fullName: "",
         email: "",
         phone: ""
       },
       submitted: false
     };

     function validateField(name, value) {
       const trimmed = value.trim();

       if (name === "fullName") {
         if (!trimmed) return "Full name is required.";
         if (trimmed.length < 2) return "Enter your full name.";
       }

       if (name === "email") {
         if (!trimmed) return "Email address is required.";
         if (!patterns.email.test(trimmed)) return "Enter a valid email address.";
       }

       if (name === "phone" && trimmed && !patterns.phone.test(trimmed)) {
         return "Enter a valid phone number in the expected format.";
       }

       return "";
     }

     function validateForm() {
       return {
         fullName: validateField("fullName", state.values.fullName),
         email: validateField("email", state.values.email),
         phone: validateField("phone", state.values.phone)
       };
     }

     function Field({ id, label, type, placeholder, value, error, helperText }) {
       const helperId = helperText ? id + "-helper" : "";
       const errorId = id + "-error";
       const describedBy = [helperId, error ? errorId : ""].filter(Boolean).join(" ");

       return `
         <div class="form-field">
           <label for="${id}">${label}</label>
           <input
             id="${id}"
             name="${id}"
             type="${type}"
             placeholder="${placeholder}"
             value="${escapeHtml(value)}"
             aria-invalid="${error ? "true" : "false"}"
             aria-describedby="${describedBy}"
           />
           ${helperText ? `<div class="helper-text" id="${helperId}">${helperText}</div>` : ""}
           <div class="error-message" id="${errorId}">${error || ""}</div>
         </div>
       `;
     }

     function ContactForm() {
       return `
         <main class="page-shell">
           <section class="support-card">
             <p class="eyebrow">Support</p>
             <h1>Contact our support team</h1>
             <p class="intro">
               Send us your details and we will follow up with the right help as quickly as possible.
             </p>
             <form id="support-form" novalidate>
               ${Field({
                 id: "fullName",
                 label: "Full name",
                 type: "text",
                 placeholder: "Jordan Lee",
                 value: state.values.fullName,
                 error: state.errors.fullName
               })}
               ${Field({
                 id: "email",
                 label: "Email address",
                 type: "email",
                 placeholder: "jordan@example.com",
                 value: state.values.email,
                 error: state.errors.email
               })}
               ${Field({
                 id: "phone",
                 label: "Phone number",
                 type: "tel",
                 placeholder: "+1 (555) 123-4567",
                 value: state.values.phone,
                 error: state.errors.phone,
                 helperText: "Optional. Use digits with spaces, dashes, parentheses, or a leading +, for example: +1 (555) 123-4567."
               })}
               <button class="submit-button" type="submit">Submit</button>
               <div class="success-message" aria-live="polite">
                 ${state.submitted ? "Your support request is ready to be sent." : ""}
               </div>
             </form>
           </section>
         </main>
       `;
     }

     function escapeHtml(value) {
       return value
         .replaceAll("&", "&amp;")
         .replaceAll("<", "&lt;")
         .replaceAll(">", "&gt;")
         .replaceAll('"', "&quot;")
         .replaceAll("'", "&#39;");
     }

     function render() {
       document.getElementById("app").innerHTML = ContactForm();

       const form = document.getElementById("support-form");
       const fields = ["fullName", "email", "phone"];

       fields.forEach((field) => {
         const input = document.getElementById(field);
         input.addEventListener("input", (event) => {
           state.values[field] = event.target.value;
           state.errors[field] = validateField(field, event.target.value);
           state.submitted = false;
           render();
           document.getElementById(field).focus();
           const nextValue = state.values[field];
           document.getElementById(field).setSelectionRange(nextValue.length, nextValue.length);
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         state.errors = validateForm();
         state.submitted = !Object.values(state.errors).some(Boolean);
         render();
       });
     }

