 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8" />
   <meta name="viewport" content="width=device-width, initial-scale=1.0" />
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1220;
       --panel: rgba(15, 23, 42, 0.92);
       --panel-border: rgba(148, 163, 184, 0.16);
       --text: #e5eefb;
       --muted: #94a3b8;
       --accent: #60a5fa;
       --accent-strong: #3b82f6;
       --error: #fda4af;
       --error-strong: #fb7185;
       --input: rgba(15, 23, 42, 0.75);
       --shadow: 0 24px 70px rgba(2, 6, 23, 0.45);
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top, rgba(59, 130, 246, 0.22), transparent 32%),
         linear-gradient(180deg, #020617 0%, #0b1220 100%);
       color: var(--text);
       display: grid;
       place-items: center;
       padding: 24px;
     }

     .page-shell {
       width: min(100%, 540px);
     }

     .support-card {
       background: var(--panel);
       border: 1px solid var(--panel-border);
       border-radius: 24px;
       box-shadow: var(--shadow);
       backdrop-filter: blur(20px);
       padding: 32px;
     }

     .eyebrow {
       margin: 0 0 8px;
       color: var(--accent);
       font-size: 0.8rem;
       font-weight: 700;
       letter-spacing: 0.08em;
       text-transform: uppercase;
     }

     h1 {
       margin: 0 0 12px;
       font-size: clamp(1.9rem, 5vw, 2.4rem);
       line-height: 1.1;
     }

     .intro {
       margin: 0 0 28px;
       color: var(--muted);
       line-height: 1.6;
     }

     form {
       display: grid;
       gap: 18px;
     }

     .form-field {
       display: grid;
       gap: 8px;
     }

     label {
       font-size: 0.95rem;
       font-weight: 600;
     }

     input {
       width: 100%;
       border: 1px solid rgba(148, 163, 184, 0.24);
       border-radius: 14px;
       background: var(--input);
       color: var(--text);
       padding: 14px 16px;
       font: inherit;
       outline: none;
       transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
     }

     input::placeholder {
       color: #64748b;
     }

     input:focus {
       border-color: var(--accent);
       box-shadow: 0 0 0 4px rgba(96, 165, 250, 0.14);
     }

     input[aria-invalid="true"] {
       border-color: var(--error-strong);
       box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.12);
     }

     .helper-text,
     .error-message,
     .success-message {
       font-size: 0.9rem;
       line-height: 1.5;
     }

     .helper-text {
       color: var(--muted);
     }

     .error-message {
       min-height: 1.35em;
       color: var(--error);
     }

     .success-message {
       margin: 6px 0 0;
       color: #86efac;
       min-height: 1.5em;
     }

     .submit-button {
       margin-top: 6px;
       border: 0;
       border-radius: 14px;
       padding: 14px 18px;
       background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
       color: #eff6ff;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
       box-shadow: 0 16px 32px rgba(37, 99, 235, 0.32);
     }

     .submit-button:hover {
       transform: translateY(-1px);
       filter: brightness(1.04);
     }

     .submit-button:active {
       transform: translateY(0);
     }

     @media (max-width: 600px) {
       .support-card {
         padding: 24px;
       }
     }
   </style>
 </head>
 <body>
   <div id="app"></div>
   <script>
     const patterns = {
       email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
       phone: /^\+?[0-9\s\-().]{7,20}$/
     };

     const state = {
       values: {
         fullName: "",
         email: "",
         phone: ""
       },
       errors: {
         fullName: "",
         email: "",
         phone: ""
       },
       submitted: false
     };

     function validateField(name, value) {
       const trimmed = value.trim();

       if (name === "fullName") {
         if (!trimmed) return "Full name is required.";
         if (trimmed.length < 2) return "Enter your full name.";
       }

       if (name === "email") {
         if (!trimmed) return "Email address is required.";
         if (!patterns.email.test(trimmed)) return "Enter a valid email address.";
       }

       if (name === "phone" && trimmed && !patterns.phone.test(trimmed)) {
         return "Enter a valid phone number in the expected format.";
       }

       return "";
     }

     function validateForm() {
       return {
         fullName: validateField("fullName", state.values.fullName),
         email: validateField("email", state.values.email),
         phone: validateField("phone", state.values.phone)
       };
     }

     function Field({ id, label, type, placeholder, value, error, helperText }) {
       const helperId = helperText ? id + "-helper" : "";
       const errorId = id + "-error";
       const describedBy = [helperId, error ? errorId : ""].filter(Boolean).join(" ");

       return `
         <div class="form-field">
           <label for="${id}">${label}</label>
           <input
             id="${id}"
             name="${id}"
             type="${type}"
             placeholder="${placeholder}"
             value="${escapeHtml(value)}"
             aria-invalid="${error ? "true" : "false"}"
             aria-describedby="${describedBy}"
           />
           ${helperText ? `<div class="helper-text" id="${helperId}">${helperText}</div>` : ""}
           <div class="error-message" id="${errorId}">${error || ""}</div>
         </div>
       `;
     }

     function ContactForm() {
       return `
         <main class="page-shell">
           <section class="support-card">
             <p class="eyebrow">Support</p>
             <h1>Contact our support team</h1>
             <p class="intro">
               Send us your details and we will follow up with the right help as quickly as possible.
             </p>
             <form id="support-form" novalidate>
               ${Field({
                 id: "fullName",
                 label: "Full name",
                 type: "text",
                 placeholder: "Jordan Lee",
                 value: state.values.fullName,
                 error: state.errors.fullName
               })}
               ${Field({
                 id: "email",
                 label: "Email address",
                 type: "email",
                 placeholder: "jordan@example.com",
                 value: state.values.email,
                 error: state.errors.email
               })}
               ${Field({
                 id: "phone",
                 label: "Phone number",
                 type: "tel",
                 placeholder: "+1 (555) 123-4567",
                 value: state.values.phone,
                 error: state.errors.phone,
                 helperText: "Optional. Use digits with spaces, dashes, parentheses, or a leading +, for example: +1 (555) 123-4567."
               })}
               <button class="submit-button" type="submit">Submit</button>
               <div class="success-message" aria-live="polite">
                 ${state.submitted ? "Your support request is ready to be sent." : ""}
               </div>
             </form>
           </section>
         </main>
       `;
     }

     function escapeHtml(value) {
       return value
         .replaceAll("&", "&amp;")
         .replaceAll("<", "&lt;")
         .replaceAll(">", "&gt;")
         .replaceAll('"', "&quot;")
         .replaceAll("'", "&#39;");
     }

     function syncField(field) {
       const input = document.getElementById(field);
       const error = document.getElementById(field + "-error");
       const helper = document.getElementById(field + "-helper");
       const describedBy = [helper ? helper.id : "", state.errors[field] ? error.id : ""].filter(Boolean).join(" ");

       input.setAttribute("aria-invalid", state.errors[field] ? "true" : "false");
       if (describedBy) {
         input.setAttribute("aria-describedby", describedBy);
       } else {
         input.removeAttribute("aria-describedby");
       }
       error.textContent = state.errors[field];
     }

     function syncSuccessMessage() {
       document.querySelector(".success-message").textContent = state.submitted
         ? "Your support request is ready to be sent."
         : "";
     }

     function bindEvents() {
       const form = document.getElementById("support-form");
       const fields = ["fullName", "email", "phone"];

       fields.forEach((field) => {
         const input = document.getElementById(field);
         input.addEventListener("input", (event) => {
           state.values[field] = event.target.value;
           state.errors[field] = validateField(field, event.target.value);
           state.submitted = false;
           syncField(field);
           syncSuccessMessage();
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         state.errors = validateForm();
         state.submitted = !Object.values(state.errors).some(Boolean);

         fields.forEach(syncField);
         syncSuccessMessage();
       });
     }

     function render() {
       document.getElementById("app").innerHTML = ContactForm();
       bindEvents();
     }

     render();
   </script>
 </body>
 </html>

