      form.addEventListener("submit", (event) => {
        event.preventDefault();
        state.errors = validateForm();
        state.submitted = !Object.values(state.errors).some(Boolean);

        fields.forEach(syncField);
        syncSuccessMessage();
      });
    }

    function render() {
      document.getElementById("app").innerHTML = ContactForm();
      bindEvents();
    }

